 * @return {number[][]}
 */
var reverseSubmatrix = function(grid, x, y, k) {
    const m = grid.length;
    const n = grid[0].length;

    const res = Array.from({ length: m }, () => new Array(n).fill(0));

    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            if (row >= x && row < x + k && col >= y && col < y + k) {
                const drow = k - 1 - row + 2 * x;
                res[drow][col] = grid[row][col];
            } else {
                res[row][col] = grid[row][col];
            }
        }
    }

    return res;
};

/**
 * @param {number[][]} grid
 * @param {number} x
 * @param {number} y
 * @param {number} k
 * @return {number[][]}
 */
var reverseSubmatrix = function(grid, x, y, k) {
    const m = grid.length;
    const n = grid[0].length;
    const inv_m = 2 * x + k - 1;

    const res = Array.from({ length: m }, () => new Array(n).fill(0));

    for (let row = 0; row < m; row++) {
        for (let col = 0; col < n; col++) {
            if (row >= x && row < x + k && col >= y && col < y + k) {
                res[inv_m - row][col] = grid[row][col];
            } else {
                res[row][col] = grid[row][col];
            }
        }
    }

    return res;
};

/**
 * @param {number[][]} grid
 * @param {number} x
 * @param {number} y
 * @param {number} k
 * @return {number[][]}
 */
var reverseSubmatrix = function(grid, x, y, k) {
    const rows = k / 2;

    for (let row = 0; row < rows; row++) {
        for (let col = 0; col < k; col++) {
            const inv_row = k - 1 - row;

            if (row !== inv_row) {
                const temp = grid[x + row][y + col];
                grid[x + row][y + col] = grid[x + inv_row][y + col];
                grid[x + inv_row][y + col] = temp;
            }
        }
    }

    return grid;
};
